'use strict';

// MODULES //

var isInteger = require( '@stdlib/assert/is-integer' ).isPrimitive;
var broadcastScalar = require( '@stdlib/ndarray/base/broadcast-scalar' );
var maybeBroadcastArray = require( '@stdlib/ndarray/base/maybe-broadcast-array' );
var ndims = require( '@stdlib/ndarray/base/ndims' );
var getDefault = require( '@stdlib/ndarray/defaults' ).get;
var format = require( '@stdlib/string/format' );


// VARIABLES //

var DEFAULT_DTYPE = getDefault( 'dtypes.integer_index' );


// MAIN //

/**
* Broadcasts an index argument to match the shape of the non-core dimensions.
*
* ## Notes
*
* -   When a list of dimensions is not provided, the operation is performed across all dimensions, and, thus, an ndarray index argument is expected to be a zero-dimensional ndarray.
*
* @private
* @param {(ndarray|NonNegativeInteger)} idx - index argument
* @param {string} name - argument ordinal name
* @param {NonNegativeIntegerArray} shape - shape of the non-core dimensions
* @param {string} order - memory layout order
* @param {boolean} hasDims - boolean indicating whether a list of dimensions was provided
* @throws {TypeError} index argument must be a zero-dimensional ndarray
* @returns {ndarray} ndarray containing index values
*/
function broadcastIndex( idx, name, shape, order, hasDims ) {
	if ( isInteger( idx ) ) {
		return broadcastScalar( idx, DEFAULT_DTYPE, shape, order );
	}
	if ( hasDims ) {
		return maybeBroadcastArray( idx, shape );
	}
	if ( ndims( idx ) === 0 ) {
		return idx;
	}
	throw new TypeError( format( 'invalid argument. %s argument must be a zero-dimensional ndarray.', name ) );
}


// EXPORTS //

module.exports = broadcastIndex;
